import subprocess, os
def run(args, env=None, input_data=None):
    e=dict(os.environ); e.pop("TERM",None)
    if env:
        for k,v in env.items():
            if v is None: e.pop(k,None)
            else: e[k]=v
    kw={}
    if input_data is not None: kw['input']=input_data
    return subprocess.run(["./executable"]+args, capture_output=True, env=e, **kw)
def show(args, **kw):
    r=run(args, **kw)
    so=r.stdout; se=r.stderr
    # summarize stderr first line only if help present
    def summ(b):
        if b.startswith(b'jp2a 1.0.8') or b'\nUsage: jp2a' in b:
            first=b.split(b'\n\n')[0] if not b.startswith(b'jp2a') else b'<<HELP/VERSION>>'
            # keep prefix before help
            idx=b.find(b'jp2a 1.0.8')
            return repr(b[:idx])+f" +HELP len={len(b)}"
        return repr(b[:500])
    print(f"{args} kw={kw.keys()} exit={r.returncode} out={summ(so)} err={summ(se)}")
    return r
PY
