package main

import (
 "image"
 "image/color"
 "image/jpeg"
 "os"
 "strconv"
)

func main(){
 mode:=os.Args[1]
 out:=os.Args[2]
 w,_:=strconv.Atoi(os.Args[3]); h,_:=strconv.Atoi(os.Args[4])
 q:=95; if len(os.Args)>6 { q,_=strconv.Atoi(os.Args[6]) }
 var img image.Image
 if mode=="gray" {
   v:=uint8(0); if len(os.Args)>5 { vv,_:=strconv.Atoi(os.Args[5]); v=uint8(vv)}
   m:=image.NewGray(image.Rect(0,0,w,h))
   for y:=0;y<h;y++{ for x:=0;x<w;x++{ m.SetGray(x,y,color.Gray{v}) } }
   img=m
 } else if mode=="graygradx" {
   m:=image.NewGray(image.Rect(0,0,w,h))
   for y:=0;y<h;y++{ for x:=0;x<w;x++{ m.SetGray(x,y,color.Gray{uint8(x*255/max(1,w-1))}) } }
   img=m
 } else if mode=="graygrady" {
   m:=image.NewGray(image.Rect(0,0,w,h))
   for y:=0;y<h;y++{ for x:=0;x<w;x++{ m.SetGray(x,y,color.Gray{uint8(y*255/max(1,h-1))}) } }
   img=m
 } else if mode=="grayfunc" {
   // pixel = (x + y*w) scaled? We'll encode specific pattern via args not; use checker
   m:=image.NewGray(image.Rect(0,0,w,h))
   for y:=0;y<h;y++{ for x:=0;x<w;x++{ var v uint8; if (x+y)%2==0 {v=255} else {v=0}; m.SetGray(x,y,color.Gray{v}) } }
   img=m
 } else if mode=="color" {
   r8,_:=strconv.Atoi(os.Args[5]); rest:=os.Args // dummy
   _=rest; _=r8
   // args: w h R G B
   R,_:=strconv.Atoi(os.Args[5]); G:=0; B:=0
   if len(os.Args)>7 { /* not */ }
   _=G; _=B
   // parse extra from env? simpler: use args 5,6?, we changed layout -> handle below
   m:=image.NewRGBA(image.Rect(0,0,w,h))
   // We'll read R,G,B from env
   R=atoiEnv("R",R); G=atoiEnv("G",0); B=atoiEnv("B",0)
   for y:=0;y<h;y++{ for x:=0;x<w;x++{ m.Set(x,y,color.RGBA{uint8(R),uint8(G),uint8(B),255}) } }
   img=m
 } else if mode=="colorgrad" {
   m:=image.NewRGBA(image.Rect(0,0,w,h))
   for y:=0;y<h;y++{ for x:=0;x<w;x++{ m.Set(x,y,color.RGBA{uint8(x*255/max(1,w-1)), uint8(y*255/max(1,h-1)), 128,255}) } }
   img=m
 }
 f,_:=os.Create(out); defer f.Close()
 jpeg.Encode(f, img, &jpeg.Options{Quality:q})
}
func max(a,b int)int{ if a>b {return a}; return b }
func atoiEnv(n string, d int)int{ if v:=os.Getenv(n); v!="" { i,_:=strconv.Atoi(v); return i}; return d }
GO
