    rows=[]
    # split by <br/>
    parts=r.stdout.decode().split("<br/>")
    for p in parts:
        row=[int(m.group(1)[0:2],16) for m in re.finditer(r"<span style='color:#([0-9a-f]{6});[^']*'>.*?</span>",p)]
        if row: rows.append(row)
    return rows

gen("point",64,64,32,32)
for sz in ["64x64","64x32","32x64"]:
    v=vals(sz)
    # print nonzero
    nz=[(x,y,v[y][x]) for y in range(len(v)) for x in range(len(v[0])) if v[y][x]!=0]
    print("point32,32",sz,nz)
gen("col",64,64,32)
for sz in ["64x64"]:
    v=vals(sz); print("col",sz, [(x,v[0][x]) for x in range(len(v[0])) if v[0][x]!=0], "rowcheck same?", all(row==v[0] for row in v))
gen("row",64,64,32)
for sz in ["64x64"]:
    v=vals(sz); print("row",sz, [(y,v[y][0]) for y in range(len(v)) if v[y][0]!=0])
