import subprocess, sys, re
sys.path.insert(0,'/tmp'); from run import run
def gen(mode,w,h,*args):
    a=["/tmp/gen2",mode,"/tmp/t.jpg",str(w),str(h)]+[str(x) for x in args]
    subprocess.run(a,check=True)
def rowvals(W,H,ow,oh):
    r=run([f"--size={ow}x{oh}","--html","--html-raw","--colors","/tmp/t.jpg"])
    rows=[]
    for p in r.stdout.decode().split("<br/>"):
        row=[int(m.group(1)[0:2],16) for m in re.finditer(r"<span style='color:#([0-9a-f]{6});[^']*'>.*?</span>",p)]
        if row: rows.append(row)
    return rows
def matrix(W,ow):
    # returns list per source col of list per dest
    M=[]
    for px in range(W):
        gen("col",W,16,px)
        v=rowvals(W,16,ow,1)
        M.append(v[0])
    return M
def show(W,ow):
    M=matrix(W,ow)
    print(f"W={W} -> {ow}")
    for s,row in enumerate(M):
        nz=[(d,row[d]) for d in range(ow) if row[d]!=0]
        print(f" s{s}: {nz} sum={sum(row)}")
    # also per dest sum over s (for uniform response should be 255 per dest)
    print(" dest sums", [sum(M[s][d] for s in range(W)) for d in range(ow)])
if __name__=="__main__":
    for W,ow in [(12,4),(12,3),(12,6),(12,12),(10,3),(10,4),(16,5),(20,8)]:
        show(W,ow)
