import sys, re
sys.path.insert(0,'/tmp'); from run import run
def get(file="assets/grind.jpg", size="80x40"):
    rh=run(["--size="+size,"--html","--html-raw","--colors",file])
    spans=[]
    for m in re.finditer(rb"<span style='color:#([0-9a-f]{6});[^']*'>(.*?)</span>", rh.stdout):
        hexv=m.group(1).decode(); spans.append((int(hexv[0:2],16),int(hexv[2:4],16),int(hexv[4:6],16)))
    ra=run(["--size="+size,"--colors",file])
    # token parse ansi output: iterate
    s=ra.stdout; i=0; codes=[]
    while i < len(s):
        if s[i:i+1]==b'\x1b':
            m=re.match(rb'\x1b\[(\d+)m', s[i:]); code=int(m.group(1)); i+=m.end()
            # next char is a byte (could be space etc)
            ch=s[i:i+1]; i+=1
            # expect reset
            m2=re.match(rb'\x1b\[0m', s[i:]); 
            if m2: i+=m2.end()
            codes.append(code)
        elif s[i:i+1]==b'\n':
            i+=1
        else:
            codes.append(None); i+=1
    print("spans",len(spans),"codes",len(codes))
    return list(zip(spans,codes))
if __name__=="__main__":
    data=get()
    from collections import Counter
    print(Counter(c for rgb,c in data))
    for rgb,c in data[:50]: print(rgb,c)
    # save
    import pickle; pickle.dump(data, open("/tmp/data.pkl","wb"))
