static int opt_width = 0;
static int opt_height = 0;
static int size_given = 0;        /* width+height given via --size */
static int width_individual = 0;  /* width given via --width */
static int height_individual = 0; /* height given via --height */
static int border = 0;
static int use_colors = 0;
static int debug_flag = 0;
static int verbose_flag = 0;
static int fill_flag = 0;
static int flipx_flag = 0;
static int flipy_flag = 0;
static int grayscale_flag = 0;
static int html_flag = 0;
static int html_raw_flag = 0;
static int html_no_bold = 0;
static int html_fontsize = 8;
static const char *html_title = "jp2a converted image";
static int invert_flag = 0;
static int clear_flag = 0;
static const char *output_filename = NULL;
static float weight_r = 0.2989f;
static float weight_g = 0.5866f;
static float weight_b = 0.1145f;

enum term_mode { MODE_FIT = 0, MODE_ZOOM, MODE_TERM_WIDTH, MODE_TERM_HEIGHT };
static int term_mode = MODE_FIT;
static int term_cols = 80;
static int term_rows = 24; /* raw rows as reported by setupterm */

/* ------------------------------------------------------------------ */
typedef struct {
    unsigned char *data;
    size_t size;
    size_t cap;
} membuf;

static void membuf_append(membuf *b, const void *src, size_t n) {
    if (b->size + n + 1 > b->cap) {
        size_t ncap = (b->size + n + 1) * 2 + 64;
        unsigned char *nd = realloc(b->data, ncap);
        if (!nd) return;
        b->data = nd; b->cap = ncap;
    }
    memcpy(b->data + b->size, src, n);
    b->size += n;
    if (b->data) b->data[b->size] = 0;
}

static size_t curl_write_cb(void *ptr, size_t size, size_t nmemb, void *userdata) {
    size_t n = size * nmemb;
    membuf_append((membuf *)userdata, ptr, n);
    return n;
}

static int is_url(const char *s) {
    static const char *schemes[] = {
        "http://", "https://", "ftp://", "ftps://", "file://", "tftp://", NULL
    };
    int i;
    for (i = 0; schemes[i]; i++) {
        size_t len = strlen(schemes[i]);
        if (strncmp(s, schemes[i], len) == 0) return 1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* terminal size via ncurses setupterm (no screen initialisation).    */
static void get_terminal_size_or_exit(void) {
    const char *term = getenv("TERM");
    int err = 0;
    if (term == NULL) {
        fprintf(stderr, "Environment variable TERM not set.\n");
        exit(1);
    }
    if (setupterm((char *)term, STDOUT_FILENO, &err) != OK || err != 1) {
        fprintf(stderr, "Terminal type '%s' not recognized.\n", term);
        exit(1);
    }
    term_cols = columns;
    term_rows = lines;
    if (term_cols <= 0) term_cols = 80;
    if (term_rows <= 0) term_rows = 24;
}

static int round_half_up(double x) {
    return (int)floor(x + 0.5);
}

/* calculate height from width; bumps *width until height >= 1 */
static int calc_height_from_width(int *width_io, int src_w, int src_h) {
    int w = *width_io;
    int h;
    for (;;) {
        double hval = round((double)w * (double)src_h / (double)src_w / 2.0);
        h = (int)hval;
        if (h >= 1) break;
        w++;
        if (w > 2000000000) break;
    }
    *width_io = w;
    return h;
}
/* calculate width from height; bumps *height until width >= 1 */
static int calc_width_from_height(int *height_io, int src_w, int src_h) {
    int h = *height_io;
    int w;
    for (;;) {
        double wval = round((double)h * (double)src_w / (double)src_h * 2.0);
        w = (int)wval;
        if (w >= 1) break;
        h++;
        if (h > 2000000000) break;
    }
    *height_io = h;
    return w;
}

static void compute_output_dimensions(int src_w, int src_h, int *out_w, int *out_h) {
    int eff_term_h = term_rows - 1;
    if (term_mode == MODE_ZOOM) {
        *out_w = term_cols;
        *out_h = eff_term_h;
        return;
    }
    if (term_mode == MODE_TERM_WIDTH) {
        int w = term_cols;
        int h = calc_height_from_width(&w, src_w, src_h);
        *out_w = w; *out_h = h;
        return;
    }
    if (term_mode == MODE_TERM_HEIGHT) {
        int h = eff_term_h;
        int w;
        if (h < 1) {
            /* mirrors the original's "Invalid" path for degenerate cases */
            fprintf(stderr, "Invalid width or height specified\n");
            exit(1);
        }
        w = calc_width_from_height(&h, src_w, src_h);
        *out_w = w; *out_h = h;
        return;
    }
    /* MODE_FIT */
    if (opt_width > 0 && opt_height > 0) {
        *out_w = opt_width; *out_h = opt_height;
    } else if (opt_width > 0) {
        int w = opt_width;
        int h = calc_height_from_width(&w, src_w, src_h);
        *out_w = w; *out_h = h;
    } else if (opt_height > 0) {
        int h = opt_height;
        int w = calc_width_from_height(&h, src_w, src_h);
        *out_w = w; *out_h = h;
    } else if (opt_width < 0 || opt_height < 0) {
        *out_w = opt_width; *out_h = opt_height;
    } else {
        /* fit into (term_cols, term_rows-1) box */
        int maxh = eff_term_h;
        double scale_w, scale_h;
        if (maxh < 1) maxh = 1;
        scale_w = (double)term_cols / (double)src_w;
        scale_h = (double)(maxh * 2) / (double)src_h;
        if (scale_w < scale_h) {
            int w = term_cols;
            int h = calc_height_from_width(&w, src_w, src_h);
            if (h > maxh && eff_term_h >= 1 && term_rows > 1) {
                /* height-limited after all due to the +1 quirk handled below */
            }
            /* If the width-computed height does not fit, height rules.   */
            if (h > maxh) {
                int hh = eff_term_h;
                int ww;
                if (hh < 1) { fprintf(stderr, "Invalid width or height specified\n"); exit(1); }
                ww = calc_width_from_height(&hh, src_w, src_h);
                *out_w = ww; *out_h = hh;
            } else {
                *out_w = w; *out_h = h;
            }
        } else {
            int hh = eff_term_h;
            int ww;
            if (hh < 1) { fprintf(stderr, "Invalid width or height specified\n"); exit(1); }
            ww = calc_width_from_height(&hh, src_w, src_h);
            *out_w = ww; *out_h = hh;
        }
        /* scale-model correction: covers 33x11 -> 32x10 style cases */
        {
            double s_w = (double)term_cols / (double)src_w;
            double s_h = (double)((term_rows - 1) * 2) / (double)src_h;
            double s = s_w < s_h ? s_w : s_h;
            int sw = round_half_up(src_w * s);
            int sh = round_half_up(src_h * s / 2.0);
            /* only use the pure scale result when both are >= 1 */
            if (sw >= 1 && sh >= 1) { *out_w = sw; *out_h = sh; }
            else if (sh < 1) {
                int w = sw < 1 ? 1 : sw;
                int h = calc_height_from_width(&w, src_w, src_h);
                *out_w = w; *out_h = h;
            } else if (sw < 1) {
                int h = sh;
                int w = calc_width_from_height(&h, src_w, src_h);
                *out_w = w; *out_h = h;
            }
        }
    }
}

/* ------------------------------------------------------------------ */
typedef struct {
    float r, g, b;    /* averaged channel values */
    float lum;        /* averaged luminance */
    int ri, gi, bi;   /* rounded channels */
    int ch_index;
    unsigned char ch;
} dest_pixel;

typedef struct {
    int width, height;
    int num_components; /* jpeg components */
    int out_components; /* components per scanline from libjpeg */
    int is_color;       /* out_components == 3 */
    unsigned char *pixels; /* source pixels, width*height*out_comps */
    dest_pixel *dest;
    int dest_w, dest_h;
} image_t;

/* maps one destination coordinate to an inclusive source window */
static void source_window(int src_size, int dest_size, int i, int *s0, int *s1) {
    double step = (double)(src_size - 1) / (double)dest_size;
    double a = round((double)i * step);
    double b = round((double)(i + 1) * step);
    *s0 = (int)a; *s1 = (int)b;
}

static void compute_dest(image_t *img) {
    int dw = img->dest_w, dh = img->dest_h;
    int sw = img->width, sh = img->height;
    int x, y, sx, sy;
    int pal_len = (int)strlen(palette);
    for (y = 0; y < dh; y++) {
        int y0, y1; source_window(sh, dh, y, &y0, &y1);
        for (x = 0; x < dw; x++) {
            int x0, x1; source_window(sw, dw, x, &x0, &x1);
            double sum_r = 0, sum_g = 0, sum_b = 0, sum_l = 0;
            double cnt = 0;
            dest_pixel *p;
            for (sy = y0; sy <= y1; sy++) {
                if (sy < 0 || sy >= sh) continue;
                for (sx = x0; sx <= x1; sx++) {
                    const unsigned char *sp;
                    int r, g, b;
                    float lum;
                    if (sx < 0 || sx >= sw) continue;
                    sp = img->pixels + ((size_t)sy * sw + sx) * img->out_components;
                    if (img->is_color) {
                        r = sp[0]; g = sp[1]; b = sp[2];
                        lum = (float)r * weight_r + (float)g * weight_g + (float)b * weight_b;
                    } else {
                        r = g = b = sp[0];
                        lum = (float)sp[0];
                    }
                    sum_r += r; sum_g += g; sum_b += b; sum_l += lum;
                    cnt += 1.0;
                }
            }
            p = &img->dest[(size_t)y * dw + x];
            if (cnt <= 0) cnt = 1;
            p->r = (float)(sum_r / cnt);
            p->g = (float)(sum_g / cnt);
            p->b = (float)(sum_b / cnt);
            p->lum = (float)(sum_l / cnt);
            p->ri = (int)floor(p->r + 0.5f);
            p->gi = (int)floor(p->g + 0.5f);
            p->bi = (int)floor(p->b + 0.5f);
            {
                float intensity = invert_flag ? (255.0f - p->lum) : p->lum;
                int idx = (int)floor((double)intensity * (pal_len - 1) / 255.0 + 0.5);
                p->ch_index = idx;
                if (idx < 0 || idx >= pal_len) p->ch = 0;
                else p->ch = (unsigned char)palette[idx];
            }
        }
    }
}

/* ---------------- output printing ---------------- */
static FILE *out_fp = NULL;

static const char *html_char_escape(unsigned char ch, char *buf) {
    switch (ch) {
        case ' ': return "&nbsp;";
        case '<': return "&lt;";
        case '>': return "&gt;";
        case '&': return "&amp;";
        case 0: return "";
        default: buf[0] = (char)ch; buf[1] = 0; return buf;
    }
}

/* ANSI colour for colour images; returns -1 for "no escape", else code. */
static int ansi_color_code(const image_t *img, const dest_pixel *p) {
    int r = p->ri, g = p->gi, b = p->bi;
    (void)img;
    /* grayscale flag: white when bright enough */
    if (grayscale_flag) {
        if (p->lum >= 178.5f) return 37;
        return -1;
    }
    if (!img->is_color) {
        if (p->lum < 0.5f) return 37;
        if (p->lum >= 242.5f) return 1;
        return -1;
    }
    /* colour image: classify by channel relationships (approx. of the
     * original heuristic; refined by black-box sampling) */
    {
        int mx = r; if (g > mx) mx = g; if (b > mx) mx = b;
        int mn = r; if (g < mn) mn = g; if (b < mn) mn = b;
        /* achromatic */
        if (mx - mn <= 24) {
            /* see analysis in ansi_classify() below */
            extern int ansi_classify(int,int,int);
            return ansi_classify(r, g, b);
        }
        return ansi_classify(r, g, b);
    }
}

static void print_pixel_text(const image_t *img, const dest_pixel *p) {
    if (use_colors || grayscale_flag) {
        int code = ansi_color_code(img, p);
        if (code >= 0) {
            int shown = code;
            if (fill_flag && code >= 30 && code <= 37) shown = code + 10;
            fprintf(out_fp, "\033[%dm", shown);
            if (p->ch) fputc(p->ch, out_fp);
            fprintf(out_fp, "\033[0m");
            return;
        }
        if (p->ch) fputc(p->ch, out_fp);
        return;
    }
    if (p->ch) fputc(p->ch, out_fp);
}

static void print_image(image_t *img) {
    int dw = img->dest_w, dh = img->dest_h;
    int x, y;
    int html_colour = (use_colors || grayscale_flag);
    if (clear_flag) fputs("\033[2J\033[0;0H", out_fp);
    if (html_flag && !html_raw_flag) {
        fprintf(out_fp, "<?xml version='1.0' encoding='ISO-8859-1'?>\n");
        fprintf(out_fp, "<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n");
        fprintf(out_fp, "<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n");
        fprintf(out_fp, "<head>\n");
        fprintf(out_fp, "<title>%s</title>\n", html_title);
        fprintf(out_fp, "<style type='text/css'>\n");
        fprintf(out_fp, "body {\n");
        if (invert_flag) fprintf(out_fp, "   background-color: white;\n");
        else fprintf(out_fp, "background-color: black;\n");
        fprintf(out_fp, "}\n");
        fprintf(out_fp, ".ascii {\n");
        fprintf(out_fp, "   font-family: Courier;\n");
        if (!html_colour) fprintf(out_fp, "   color: %s;\n", invert_flag ? "black" : "white");
        fprintf(out_fp, "   font-size:%dpt;\n", html_fontsize);
        fprintf(out_fp, "   font-weight: %s;\n", html_no_bold ? "normal" : "bold");
        fprintf(out_fp, "}\n");
        fprintf(out_fp, "</style>\n");
        fprintf(out_fp, "</head>\n");
        fprintf(out_fp, "<body>\n");
        fprintf(out_fp, "<div class='ascii'><pre>\n");
    }
    if (border) {
        fputc('+', out_fp);
        for (x = 0; x < dw; x++) fputc('-', out_fp);
        fputc('+', out_fp);
        fputc('\n', out_fp);
    }
    for (y = 0; y < dh; y++) {
        int sy = flipy_flag ? (dh - 1 - y) : y;
        if (border) fputc('|', out_fp);
        for (x = 0; x < dw; x++) {
            int sx = flipx_flag ? (dw - 1 - x) : x;
            const dest_pixel *p = &img->dest[(size_t)sy * dw + sx];
            if (html_flag && html_colour) {
                char tmp[2];
                int fr, fg_, fb;
                int br = p->ri, bg_ = p->gi, bb = p->bi;
                /* effective channels for colour display */
                float er, eg, eb, elum;
                if (grayscale_flag || !img->is_color) {
                    er = eg = eb = p->lum;
                    elum = p->lum;
                } else {
                    er = p->r; eg = p->g; eb = p->b; elum = p->lum;
                }
                br = (int)floor(er + 0.5f);
                bg_ = (int)floor(eg + 0.5f);
                bb = (int)floor(eb + 0.5f);
                if (!fill_flag) {
                    fr = br; fg_ = bg_; fb = bb;
                    fprintf(out_fp, "<span style='color:#%02x%02x%02x;'>%s</span>",
                            fr & 255, fg_ & 255, fb & 255, html_char_escape(p->ch, tmp));
                } else {
                    if (grayscale_flag || !img->is_color) {
                        fr = (int)floor(er / 2.0f + 0.5f);
                        fg_ = (int)floor(eg / 2.0f + 0.5f);
                        fb = (int)floor(eb / 2.0f + 0.5f);
                    } else {
                        fr = (int)floor((double)er * (double)elum / 255.0 + 0.5);
                        fg_ = (int)floor((double)eg * (double)elum / 255.0 + 0.5);
                        fb = (int)floor((double)eb * (double)elum / 255.0 + 0.5);
                    }
                    fprintf(out_fp, "<span style='color:#%02x%02x%02x; background-color:#%02x%02x%02x;'>%s</span>",
                            fr & 255, fg_ & 255, fb & 255, br & 255, bg_ & 255, bb & 255,
                            html_char_escape(p->ch, tmp));
                }
            } else if (html_flag) {
                if (p->ch) fputc(p->ch, out_fp);
            } else {
                print_pixel_text(img, p);
            }
        }
        if (border) fputc('|', out_fp);
        if (html_flag && html_colour) fputs("<br/>", out_fp);
        else fputc('\n', out_fp);
    }
    if (border) {
        fputc('+', out_fp);
        for (x = 0; x < dw; x++) fputc('-', out_fp);
        fputc('+', out_fp);
        fputc('\n', out_fp);
    }
    if (html_flag && !html_raw_flag) {
        fprintf(out_fp, "</pre>\n</div>\n</body>\n</html>\n");
    }
}

/* ---------------- file / url handling ---------------- */

static unsigned char *read_stream_fully(FILE *fp, size_t *out_size) {
    membuf b; memset(&b, 0, sizeof(b));
    unsigned char tmp[65536];
    size_t n;
    while ((n = fread(tmp, 1, sizeof(tmp), fp)) > 0) membuf_append(&b, tmp, n);
    *out_size = b.size;
    if (!b.data) { b.data = malloc(1); b.data[0] = 0; }
    return b.data;
}

static unsigned char *download_url(const char *url, size_t *out_size) {
    membuf b; memset(&b, 0, sizeof(b));
    CURL *curl = curl_easy_init();
    CURLcode res;
    if (!curl) { *out_size = 0; return calloc(1, 1); }
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, curl_write_cb);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &b);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(curl, CURLOPT_FAILONERROR, 1L);
    if (debug_flag) curl_easy_setopt(curl, CURLOPT_VERBOSE, 1L);
    res = curl_easy_perform(curl);
    curl_easy_cleanup(curl);
    if (res != CURLE_OK) {
        free(b.data);
        b.data = NULL; b.size = 0;
    }
    *out_size = b.size;
    if (!b.data) { b.data = malloc(1); b.data[0] = 0; }
    return b.data;
}

/* ---------------- per-file processing ---------------- */

static int process_one(const char *name) {
    unsigned char *data = NULL;
    size_t data_size = 0;
    int is_stdin_input = (strcmp(name, "-") == 0);
    int url = is_url(name);

    if (url) {
        if (verbose_flag) fprintf(stderr, "URL: %s\n", name);
        data = download_url(name, &data_size);
    } else if (is_stdin_input) {
        data = read_stream_fully(stdin, &data_size);
    } else {
        FILE *fp = fopen(name, "rb");
        if (!fp) {
            fprintf(stderr, "Can't open %s\n", name);
            return 1;
        }
        if (verbose_flag) fprintf(stderr, "File: %s\n", name);
        data = read_stream_fully(fp, &data_size);
        fclose(fp);
    }
    if (data_size == 0) {
        fprintf(stderr, "Empty input file\n");
        free(data);
        return 1;
    }

    /* libjpeg setup */
    {
        static unsigned char errbuf[1024];
        unsigned char *cinfo;
        image_t img;
        unsigned int src_w, src_h;
        int numcomp;
        int dest_w, dest_h;
        memset(errbuf, 0, sizeof(errbuf));
        jpeg_std_error(errbuf);
        cinfo = calloc(1, JPEG_STRUCT_SIZE);
        if (!cinfo) { free(data); return 1; }
        jd_set_ptr(cinfo, 0, errbuf);
        jpeg_CreateDecompress(cinfo, JPEG_LIB_VERSION, JPEG_STRUCT_SIZE);
        jpeg_mem_src(cinfo, data, (unsigned long)data_size);
        jpeg_read_header(cinfo, 1);
        src_w = jd_u32(cinfo, JD_OFF_IMAGE_W);
        src_h = jd_u32(cinfo, JD_OFF_IMAGE_H);
        numcomp = (int)jd_u32(cinfo, JD_OFF_NUMCOMP);

        compute_output_dimensions((int)src_w, (int)src_h, &dest_w, &dest_h);

        memset(&img, 0, sizeof(img));
        img.width = (int)src_w; img.height = (int)src_h;
        img.num_components = numcomp;
        img.dest_w = dest_w; img.dest_h = dest_h;

        /* allocate destination first (mirrors original failure behaviour) */
        if (dest_w > 0 && dest_h > 0) {
            img.dest = calloc((size_t)dest_w * (size_t)dest_h, sizeof(dest_pixel));
            if (!img.dest) {
                fprintf(stderr, "Not enough memory for given output dimension\n");
                jpeg_destroy_decompress(cinfo);
                free(cinfo); free(data);
                return 1;
            }
        }

        if (verbose_flag) {
            fprintf(stderr, "Source width: %u\n", src_w);
            fprintf(stderr, "Source height: %u\n", src_h);
            fprintf(stderr, "Source color components: %d\n", numcomp);
            fprintf(stderr, "Output width: %d\n", dest_w);
            fprintf(stderr, "Output height: %d\n", dest_h);
            fprintf(stderr, "Output palette (%d chars): '%s'\n", (int)strlen(palette), palette);
        }

        jpeg_start_decompress(cinfo);
        img.out_components = (int)jd_u32(cinfo, JD_OFF_OUT_COMP);
        if (img.out_components <= 0 || img.out_components > 4) img.out_components = numcomp;
        if (img.out_components <= 0) img.out_components = 1;
        img.is_color = (img.out_components == 3);
        img.pixels = malloc((size_t)src_w * (size_t)src_h * (size_t)img.out_components);
        if (!img.pixels && src_w && src_h) {
            fprintf(stderr, "Not enough memory for given output dimension\n");
            jpeg_destroy_decompress(cinfo);
            free(cinfo); free(data); free(img.dest);
            return 1;
        }
        {
            unsigned int row_stride = src_w * (unsigned int)img.out_components;
            unsigned int y;
            for (y = 0; y < src_h; y++) {
                unsigned char *row = img.pixels + (size_t)y * row_stride;
                unsigned char *rows[1]; rows[0] = row;
                jpeg_read_scanlines(cinfo, rows, 1);
                if (verbose_flag) {
                    /* progress bar: segment for this scanline */
                    float frac = (float)(y + 2) / (float)src_h;
                    int hashes = (int)(frac * 54.0f + 0.5f);
                    int i;
                    fputs("Decompressing image [", stderr);
                    for (i = 0; i < hashes; i++) fputc('#', stderr);
                    for (i = hashes; i < 54; i++) fputc('.', stderr);
                    fputs("]\r", stderr);
                    fflush(stderr);
                }
            }
        }
        jpeg_finish_decompress(cinfo);
        jpeg_destroy_decompress(cinfo);
        free(cinfo);

        if (dest_w <= 0 || dest_h <= 0) {
            /* width 0 outputs empty lines (as in the original quirk) */
            int i;
            for (i = 0; i < dest_h; i++) fputc('\n', out_fp);
            free(img.pixels); free(img.dest); free(data);
            return 0;
        }
        compute_dest(&img);
        print_image(&img);
        fflush(out_fp);
        free(img.pixels);
        free(img.dest);
        free(data);
        if (verbose_flag) fputc('\n', stderr);
        return 0;
    }
}

