static void print_help(void) {
    fputs(help_text, stderr);
}
static void print_version(void) {
    fputs(version_text, stderr);
}

int main(int argc, char **argv) {
    const char **files = NULL;
    int nfiles = 0, files_cap = 0;
    int i;
    files = malloc(sizeof(char *) * (size_t)(argc > 1 ? argc : 1));
    files_cap = argc > 1 ? argc : 1;

    for (i = 1; i < argc; i++) {
        const char *arg = argv[i];
        int dummy_w, dummy_h;
        if (strcmp(arg, "-h") == 0 || strcmp(arg, "--help") == 0) {
            print_help(); free(files); return 0;
        } else if (strcmp(arg, "-V") == 0 || strcmp(arg, "--version") == 0) {
            print_version(); free(files); return 0;
        } else if (strcmp(arg, "-b") == 0 || strcmp(arg, "--border") == 0) {
            border = 1;
        } else if (strcmp(arg, "--colors") == 0 || strcmp(arg, "--color") == 0) {
            use_colors = 1;
        } else if (strcmp(arg, "--clear") == 0) {
            clear_flag = 1;
        } else if (strcmp(arg, "-d") == 0 || strcmp(arg, "--debug") == 0) {
            debug_flag = 1;
        } else if (strcmp(arg, "--fill") == 0) {
            fill_flag = 1;
        } else if (strcmp(arg, "--html-fill") == 0) {
            fill_flag = 1;
            fprintf(stderr, "warning: --html-fill has changed to --fill\n");
        } else if (strcmp(arg, "-x") == 0 || strcmp(arg, "--flipx") == 0) {
            flipx_flag = 1;
        } else if (strcmp(arg, "-y") == 0 || strcmp(arg, "--flipy") == 0) {
            flipy_flag = 1;
        } else if (strcmp(arg, "-f") == 0 || strcmp(arg, "--term-fit") == 0) {
            term_mode = MODE_FIT;
        } else if (strcmp(arg, "--term-width") == 0) {
            term_mode = MODE_TERM_WIDTH;
        } else if (strcmp(arg, "--term-height") == 0) {
            term_mode = MODE_TERM_HEIGHT;
        } else if (strcmp(arg, "-z") == 0 || strcmp(arg, "--term-zoom") == 0) {
            term_mode = MODE_ZOOM;
        } else if (strcmp(arg, "--grayscale") == 0) {
            grayscale_flag = 1;
        } else if (strcmp(arg, "--html") == 0) {
            html_flag = 1;
        } else if (strcmp(arg, "--html-no-bold") == 0) {
            html_no_bold = 1;
        } else if (strcmp(arg, "--html-raw") == 0) {
            html_flag = 1; html_raw_flag = 1;
        } else if (strcmp(arg, "-i") == 0 || strcmp(arg, "--invert") == 0) {
            invert_flag = !invert_flag;
        } else if (strcmp(arg, "--background=dark") == 0) {
            invert_flag = 0;
        } else if (strcmp(arg, "--background=light") == 0) {
            invert_flag = 1;
        } else if (strcmp(arg, "-v") == 0 || strcmp(arg, "--verbose") == 0) {
            verbose_flag = 1;
        } else if (sscanf(arg, "--width=%d", &dummy_w) == 1) {
            opt_width = dummy_w; width_individual = 1; size_given = 0;
            /* width is read back out below; keep sscanf-target semantics */
            opt_width = dummy_w;
        } else if (sscanf(arg, "--height=%d", &dummy_h) == 1) {
            opt_height = dummy_h; height_individual = 1; size_given = 0;
        } else if (sscanf(arg, "--size=%dx%d", &dummy_w, &dummy_h) == 2) {
            opt_width = dummy_w; opt_height = dummy_h; size_given = 1;
            width_individual = 0; height_individual = 0;
        } else if (sscanf(arg, "--html-fontsize=%d", &html_fontsize) == 1) {
            /* set */
        } else if (sscanf(arg, "--red=%f", &weight_r) == 1) {
        } else if (sscanf(arg, "--green=%f", &weight_g) == 1) {
        } else if (sscanf(arg, "--blue=%f", &weight_b) == 1) {
        } else if (strncmp(arg, "--chars=", 8) == 0) {
            palette = arg + 8;
        } else if (strncmp(arg, "--output=", 9) == 0) {
            output_filename = arg + 9;
        } else if (strncmp(arg, "--html-title=", 13) == 0) {
            html_title = arg + 13;
        } else if (arg[0] != '-' || strcmp(arg, "-") == 0) {
            if (nfiles < files_cap) files[nfiles++] = arg;
        } else {
            fprintf(stderr, "Unknown option %s\n\n", arg);
            print_help();
            free(files);
            return 1;
        }
        (void)dummy_w; (void)dummy_h;
    }

    if (nfiles == 0) {
        fprintf(stderr, "No files specified.\n\n");
        print_help();
        free(files);
        return 1;
    }

    /* terminal size, when needed */
    {
        int need_term = 0;
        if (term_mode == MODE_ZOOM || term_mode == MODE_TERM_WIDTH || term_mode == MODE_TERM_HEIGHT) need_term = 1;
        else if (term_mode == MODE_FIT && opt_width == 0 && opt_height == 0) need_term = 1;
        if (need_term) get_terminal_size_or_exit();
    }

    if (strlen(palette) < 2) {
        fprintf(stderr, "You must specify at least two characters in --chars.\n");
        free(files);
        return 1;
    }

    if (opt_width < 0 || opt_height < 0) {
        fprintf(stderr, "Invalid width or height specified\n");
        free(files);
        return 1;
    }
    /* special-case observed in the original: --height alone + --term-height */
    if (term_mode == MODE_TERM_HEIGHT && height_individual && !width_individual && !size_given) {
        fprintf(stderr, "Invalid width or height specified\n");
        free(files);
        return 1;
    }

    if (weight_r + weight_g + weight_b != 1.0f) {
        fprintf(stderr, "Weights RED + GREEN + BLUE must equal 1.0\n");
        free(files);
        return 1;
    }

    /* open output */
    if (output_filename == NULL || strcmp(output_filename, "-") == 0) {
        out_fp = stdout;
    } else {
        if (output_filename[0] == '\0') {
            fprintf(stderr, "Empty output filename.\n");
            free(files);
            return 1;
        }
        out_fp = fopen(output_filename, "w");
        if (!out_fp) {
            fprintf(stderr, "Could not open '%s' for writing.\n", output_filename);
            free(files);
            return 1;
        }
    }

    curl_global_init(CURL_GLOBAL_ALL);
    {
        int ret = 0;
        for (i = 0; i < nfiles; i++) {
            ret = process_one(files[i]);
            if (ret != 0) {
                if (out_fp && out_fp != stdout) fclose(out_fp);
                free(files);
                return ret;
            }
        }
    }
    if (out_fp && out_fp != stdout) fclose(out_fp);
    free(files);
    return 0;
}
