package main
import ("image";"image/color";"image/jpeg";"os";"strconv";"strings";"math/rand")
func main(){
 mode:=os.Args[1]; out:=os.Args[2]; w,_:=strconv.Atoi(os.Args[3]); h,_:=strconv.Atoi(os.Args[4])
 m:=image.NewGray(image.Rect(0,0,w,h))
 rnd:=rand.New(rand.NewSource(42))
 blockvals:=make(map[[2]int]int)
 for by:=0; by<h/8; by++ { for bx:=0; bx<w/8; bx++ { blockvals[[2]int{bx,by}]=rnd.Intn(256) } }
 for y:=0;y<h;y++{ for x:=0;x<w;x++{
   var v int
   switch mode{
   case "col": col,_:=strconv.Atoi(os.Args[5]); if x==col {v=255}
   case "row": row,_:=strconv.Atoi(os.Args[5]); if y==row {v=255}
   case "point": px,_:=strconv.Atoi(os.Args[5]); py,_:=strconv.Atoi(os.Args[6]); if x==px && y==py {v=255}
   case "pixels":
     vals:=strings.Split(os.Args[5],","); idx:=y*w+x; vv,_:=strconv.Atoi(vals[idx]); v=vv
   case "blocks": v=blockvals[[2]int{x/8,y/8}]
   case "blockx": v=(x/8)*36; if v>255 {v=255}
   }
   m.SetGray(x,y,color.Gray{uint8(v)})
 }}
 f,_:=os.Create(out); defer f.Close(); jpeg.Encode(f,m,&jpeg.Options{Quality:100})
}
