import pickle, math
data=pickle.load(open("/tmp/vdata.pkl","rb"))
# Build starts list per case: starts = [win[0] for win], plus final boundary H-1 concept not
def cround(x): return math.floor(x+0.5)
tests=[]
def add(name, fn): tests.append((name,fn))
# families
for denom_name, denom in [("oh", lambda H,oh: oh), ("oh-1", lambda H,oh: oh-1), ("oh+1", lambda H,oh: oh+1)]:
 for num_name, num in [("H",lambda H,oh:H),("H-1",lambda H,oh:H-1),("H+1",lambda H,oh:H+1)]:
  for shift in [-1,-0.5,0,0.5]:
   for mode in ["floor","round","ceil"]:
    def make(denom=denom,num=num,shift=shift,mode=mode):
        def fn(H,oh,d):
            if d==0: return 0
            x=(d+shift)*num(H,oh)/denom(H,oh)
            return {"floor":math.floor(x),"round":cround(x),"ceil":math.ceil(x)}[mode]
        return fn
    add(f"{mode}((d{shift:+})*{num_name}/{denom_name})", make())
for name,fn in tests:
    bad=0; total=0; examples=[]
    for (H,oh),wins in data.items():
        if oh<=1: continue
        for d,(s0,s1) in enumerate(wins):
            total+=1
            try: pred=fn(H,oh,d)
            except Exception: pred=None
            if pred!=s0: bad+=1; examples.append(((H,oh,d),s0,pred))
    if bad<total*0.3:
        print(name,"bad",bad,"/",total,examples[:5])
