import sys, math
sys.path.insert(0,'/tmp')
from probe_resize import matrix
def check(W,ow):
    M=matrix(W,ow)
    bad=[]
    def start(d): return math.floor(d*(W-1)/ow+0.5)  # round half up
    for d in range(ow):
