{"command":"cat > src/ansi.c <<'C'
/* ANSI colour classification for colour (3-component) images.
 *
 * Derived from extensive black-box sampling of the reference program.
 * The rules that emerge are:
 *   - If the strongest channel exceeds the second strongest by more
 *     than 25, the colour is the primary of the strongest channel.
 *   - Otherwise, if the two strongest channels are distinct from the
 *     weakest by more than 25 and their sum reaches 230, the colour
 *     is the secondary formed by the two strongest channels.
 *   - Otherwise it is achromatic: white when green does not exceed
 *     blue, and no colour otherwise.
 */
int ansi_classify(float r, float g, float b) {
    float v[3];
    int ch[3];
    int i, j;
    v[0] = r; v[1] = g; v[2] = b;
    ch[0] = 0; ch[1] = 1; ch[2] = 2;
    /* stable descending sort by value (ties keep R,G,B order) */
    for (i = 0; i < 3; i++) {
        for (j = i + 1; j < 3; j++) {
            if (v[j] > v[i]) {
                float tv = v[i]; v[i] = v[j]; v[j] = tv;
                int tc = ch[i]; ch[i] = ch[j]; ch[j] = tc;
            }
        }
    }
    if (v[0] - v[1] > 25.0f) {
        if (ch[0] == 0) return 31;
        if (ch[0] == 1) return 32;
        return 34;
    }
    if (v[1] - v[2] > 25.0f && v[0] + v[1] >= 230.0f) {
        int a = ch[0], c = ch[1];
        int lo = a < c ? a : c;
        int hi = a < c ? c : a;
        if (lo == 0 && hi == 1) return 33;
        if (lo == 0 && hi == 2) return 35;
        return 36;
    }
    return (g <= b) ? 37 : -1;
}
